/* Golden prompts — what the model is supposed to pick, written down.
 *
 * A tool catalog has no compiler. Rename a tool, reword a description, and
 * every test still passes while assistants quietly start choosing differently.
 * These pin the intent so that drift becomes a diff.
 *
 * Two consumers, deliberately separate:
 *   goldenPrompts.test.ts       structural checks, runs in CI, free
 *   goldenPrompts.eval.test.ts  sends each prompt to a real model, opt-in
 *
 * Plain data module rather than part of a test file: importing a *.test.ts
 * from another test file re-registers its describe blocks and runs them twice.
 *
 * Living under convex/ means Convex codegen lists this in _generated/api.d.ts
 * and bundles it. It exports no Convex function, so it is inert weight — ~30KB
 * of fixture in the backend bundle, which is the price of keeping it next to
 * the catalog it describes. Move it out if that ever stops being a fair trade.
 *
 * GENERATED. Regenerate the rows from a fresh survey; do not hand-edit them
 * one at a time. */

export interface GoldenPrompt {
  prompt: string;
  lang: "id" | "en";
  /** direct = names the operation; indirect = states a goal; negative = must call nothing. */
  kind: "direct" | "indirect" | "negative";
  /** Exact tool name, or null when the right answer is to call no tool at all. */
  tool: string | null;
  /** Which sibling tool this is most likely to be confused with. */
  why: string;
}

